async function seedVocabulary() {
  const ALL_WORDS = [...A2_WORDS, ...B1_WORDS, ...B2_WORDS]

  console.log(`Jami so'zlar: ${ALL_WORDS.length}`)
  console.log('Supabase ga yuklanmoqda...')

  const BATCH_SIZE = 50
  let inserted = 0

  for (let i = 0; i < ALL_WORDS.length; i += BATCH_SIZE) {
    const batch = ALL_WORDS.slice(i, i + BATCH_SIZE)

    const { error } = await supabase
      .from('system_words')
      .upsert(batch, { onConflict: 'word' })

    if (error) {
      console.error(`Xato: ${error.message}`)
      process.exit(1)
    }

    inserted += batch.length
    console.log(`✓ ${inserted} / ${ALL_WORDS.length} yuklandi`)
  }

  console.log(`✅ Barcha ${inserted} ta so'z muvaffaqiyatli yuklandi!`)

  const a2Count = ALL_WORDS.filter(w => w.level === 'A2').length
  const b1Count = ALL_WORDS.filter(w => w.level === 'B1').length
  const b2Count = ALL_WORDS.filter(w => w.level === 'B2').length
  const phrasal = ALL_WORDS.filter(w => w.category === 'phrasal').length
  const idioms = ALL_WORDS.filter(w => w.category === 'idiom').length

  console.log(`\n📊 Statistika:`)
  console.log(`  A2: ${a2Count} so'z`)
  console.log(`  B1: ${b1Count} so'z`)
  console.log(`  B2: ${b2Count} so'z`)
  console.log(`  Phrasal verbs: ${phrasal}`)
  console.log(`  Idioms: ${idioms}`)
}

seedVocabulary().catch(error => {
  console.error('Seed skriptida xato:', error)
  process.exit(1)
})
